CARDIO.register({"item":"p210","meta":{"num":"p210","label":"210","spe":"pneumo","short":"PID interstitielles","title":"Pneumopathies interstitielles diffuses","section":"P","chapter":14,"pages":"210-230","sdd":[]},"objectives":[{"id":"p210-obj-01","rank":"B","rubric":"Contenu multimédia","title":"TDM thoracique fibrose pulmonaire idiopathique (PIC)","desc":""},{"id":"p210-obj-02","rank":"B","rubric":"Contenu multimédia","title":"Exemple de TDM thoracique d'asbestose","desc":""},{"id":"p210-obj-03","rank":"A","rubric":"Définition","title":"Définition des PID, connaître les grandes catégories de PID","desc":"(de cause connue et de cause inconnue)"},{"id":"p210-obj-04","rank":"B","rubric":"Diagnostic positif","title":"Pneumoconiose : savoir évoquer le diagnostic","desc":""},{"id":"p210-obj-05","rank":"B","rubric":"Diagnostic positif","title":"Pneumopathie d'hypersensibilité : savoir évoquer le diagnostic","desc":""},{"id":"p210-obj-06","rank":"B","rubric":"Diagnostic positif","title":"Savoir orienter l'étiologie en fonction du caractère aigu ou chronique, primitif ou secondaire et de l'état immunitaire du patient","desc":"(immunocompétence versus immunodépression)"},{"id":"p210-obj-07","rank":"B","rubric":"Étiologie","title":"Connaître les principales causes de PID secondaires","desc":"Médicament, infections, insuffisance cardiaque"},{"id":"p210-obj-08","rank":"B","rubric":"Étiologies","title":"Connaître le retentissement pulmonaire des principales maladies auto-immunes et infectieuses","desc":""},{"id":"p210-obj-09","rank":"B","rubric":"Examens complémentaires","title":"Connaître l'indication des examens d'imagerie au cours d'une pneumopathie interstitielle diffuse","desc":""},{"id":"p210-obj-10","rank":"B","rubric":"Examens complémentaires","title":"Connaître la stratégie diagnostique initiale devant une pneumopathie interstitielle diffuse","desc":""},{"id":"p210-obj-11","rank":"B","rubric":"Examens complémentaires","title":"Connaître la sémiologie TDM d'une pneumopathie interstitielle diffuse","desc":"lésions élémentaires : nodules, images linéaires, hyperdensités, hypodensités"},{"id":"p210-obj-12","rank":"B","rubric":"Examens complémentaires","title":"Connaître l'intérêt des EFR pour le diagnostic et le suivi des PID","desc":""},{"id":"p210-obj-13","rank":"B","rubric":"Examens complémentaires","title":"Connaître les principaux examens biologiques dont les examens immunologiques à effectuer devant une PID","desc":""}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"p210-qroc-001","type":"QROC","rank":"A","objective":"p210-obj-03","tags":["définition"],"difficulty":1,"question":"Comment nomme-t-on le tissu conjonctif de soutien des axes broncho-vasculaires et des septa du poumon, siège de l'atteinte des PID ?","answer":"L'interstitium pulmonaire","accept":["interstitium","interstitiel","compartiment interstitiel","tissu interstitiel"],"keywords":["interstit"],"explanation":"Les PID touchent essentiellement l'interstitium, tissu conjonctif de soutien des axes broncho-vasculaires et des septa inter- et intra-lobulaires, par un infiltrat cellulaire, œdémateux ou fibreux.","src":"p. 210-211"},{"id":"p210-qroc-002","type":"QROC","rank":"A","objective":"p210-obj-03","tags":["définition","clinique"],"difficulty":1,"question":"Quelle anomalie des échanges gazeux, souvent absente au repos, est typique d'une PID ?","answer":"Une hypoxémie à l'effort","accept":["hypoxemie a l effort","hypoxemie d effort","desaturation a l effort","desaturation d effort","desaturation au test de marche"],"keywords":["effort"],"explanation":"Dans les PID, l'hypoxémie est souvent absente au repos et ne se démasque qu'à l'effort, par exemple par une désaturation au test de marche de 6 minutes.","src":"p. 211, 220"},{"id":"p210-qroc-003","type":"QROC","rank":"A","objective":"p210-obj-03","tags":["définition"],"difficulty":1,"question":"Quelle durée d'évolution définit une PID aiguë ?","answer":"Moins de 3 semaines","accept":["moins de 3 semaines","moins de trois semaines","inferieur a 3 semaines","inferieure a 3 semaines"],"keywords":["moins","3"],"explanation":"Une PID aiguë évolue depuis moins de 3 semaines. Les PID subaiguës ou chroniques (PID-SC) relèvent d'une démarche diagnostique et d'une prise en charge fondamentalement différentes.","src":"p. 212"},{"id":"p210-qroc-004","type":"QROC","rank":"A","objective":"p210-obj-03","tags":["définition"],"difficulty":1,"question":"Selon quels deux critères classe-t-on les PID ?","answer":"Aiguë ou chronique ; cause connue ou inconnue","accept":["aigu ou chronique et cause connue ou inconnue","aigue ou chronique et cause connue ou inconnue"],"keywords":["aigu","chroni","connue"],"explanation":"Les PID se classent d'une part selon leur caractère aigu ou chronique, d'autre part selon que leur cause est connue ou inconnue.","src":"p. 210, 212"},{"id":"p210-qroc-005","type":"QROC","rank":"A","objective":"p210-obj-03","tags":["épidémiologie","définition"],"difficulty":2,"question":"Parmi les PID subaiguës ou chroniques, quelle proportion est de cause inconnue ?","answer":"65 %","accept":["65","65 %","environ 65 %","65 pour cent"],"keywords":["65"],"explanation":"D'après le tableau des 10 causes principales, 35 % des PID subaiguës ou chroniques sont de cause connue et 65 % de cause inconnue.","src":"p. 213"},{"id":"p210-qroc-006","type":"QROC","rank":"A","objective":"p210-obj-03","tags":["étiologie"],"difficulty":2,"question":"Quelles sont les trois grandes entités qui dominent les PID subaiguës ou chroniques ?","answer":"Sarcoïdose, FPI et PID des connectivites","accept":["sarcoidose fpi connectivites","sarcoidose fibrose pulmonaire idiopathique connectivites","sarcoidose fibrose pulmonaire idiopathique et connectivites"],"keywords":["sarco","connectiv"],"explanation":"Sarcoïdose, fibrose pulmonaire idiopathique et PID des connectivites prédominent parmi les PID subaiguës ou chroniques, tandis que les PID aiguës relèvent surtout d'infections et d'œdèmes cardiogéniques.","src":"p. 210"},{"id":"p210-qroc-007","type":"QROC","rank":"A","objective":"p210-obj-03","tags":["étiologie","épidémiologie"],"difficulty":1,"question":"Quelle est la PID idiopathique la plus fréquente ?","answer":"La fibrose pulmonaire idiopathique (FPI)","accept":["fpi","fibrose pulmonaire idiopathique"],"keywords":["fibrose"],"explanation":"La FPI représente environ 55 % des PID idiopathiques (la PINS environ 10 %). C'est aussi la plus fréquente des PID de cause inconnue après la sarcoïdose.","src":"p. 213, 225"},{"id":"p210-qroc-008","type":"QROC","rank":"A","objective":"p210-obj-03","tags":["définition","étiologie"],"difficulty":2,"question":"Comment nomme-t-on le groupe de PID qui comprend la FPI, la PINS et la pneumopathie organisée cryptogénique ?","answer":"Les PID idiopathiques (PID-i)","accept":["pid idiopathiques","pid idiopathique","idiopathiques","pneumopathies interstitielles idiopathiques"],"keywords":["idiopath"],"explanation":"FPI, PINS et pneumopathie organisée cryptogénique appartiennent aux PID idiopathiques (PID-i), de cause inconnue : la FPI en représente environ 55 % et la PINS environ 10 %.","src":"p. 213"},{"id":"p210-qroc-009","type":"QROC","rank":"A","objective":"p210-obj-03","tags":["définition","étiologie"],"difficulty":1,"question":"Quel groupe de PID de cause connue comprend le poumon d'éleveur d'oiseaux, le poumon de fermier et les formes domestiques ?","answer":"Les pneumopathies d'hypersensibilité (PHS)","accept":["phs","pneumopathies d hypersensibilite","pneumopathie d hypersensibilite","hypersensibilite"],"keywords":["hypersensib"],"explanation":"Le poumon d'éleveur d'oiseaux, le poumon de fermier et les PHS domestiques appartiennent aux pneumopathies d'hypersensibilité, dues à des antigènes organiques inhalés de façon répétée.","src":"p. 213, 226"},{"id":"p210-qroc-010","type":"QROC","rank":"A","objective":"p210-obj-03","tags":["définition","étiologie"],"difficulty":1,"question":"Quel terme regroupe la silicose et l'asbestose parmi les PID de cause connue ?","answer":"Les pneumoconioses","accept":["pneumoconiose","pneumoconioses"],"keywords":["pneumoconiose"],"explanation":"Les pneumoconioses sont des fibroses pulmonaires secondaires à l'inhalation de particules minérales (silice, amiante) ; ce sont le plus souvent des maladies professionnelles.","src":"p. 213, 227"},{"id":"p210-qroc-011","type":"QROC","rank":"B","objective":"p210-obj-06","tags":["étiologie","urgence"],"difficulty":1,"question":"Quelles sont les deux grandes causes qui dominent les PID aiguës ?","answer":"Infectieuses et cardiogéniques","accept":["infection et oedeme cardiogenique","infectieuse et cardiogenique","infections et oedeme aigu du poumon","causes infectieuses et cardiogeniques"],"keywords":["infect","cardio"],"explanation":"Les PID aiguës sont dominées par les causes infectieuses (pneumonies graves, germes opportunistes) et cardiogéniques (œdème aigu du poumon). Le SDRA et l'exacerbation d'une PID chronique complètent les quatre grandes étiologies.","src":"p. 210, 212"},{"id":"p210-qroc-012","type":"QROC","rank":"B","objective":"p210-obj-10","tags":["diagnostic","urgence"],"difficulty":1,"question":"Quel bilan est indispensable devant une PID aiguë non fébrile ?","answer":"Le bilan cardiologique","accept":["bilan cardiologique","cardiologique","ecg bnp et echographie cardiaque","ecg bnp ett"],"keywords":["cardi"],"explanation":"En l'absence de fièvre, l'œdème cardiogénique est l'hypothèse à écarter en priorité : ECG, BNP et échographie cardiaque font partie des éléments du diagnostic.","src":"p. 210, 212"},{"id":"p210-qroc-013","type":"QROC","rank":"B","objective":"p210-obj-10","tags":["diagnostic","urgence"],"difficulty":1,"question":"Quel examen est l'examen clé d'une PID aiguë fébrile ou survenant chez un immunodéprimé ?","answer":"Le lavage broncho-alvéolaire (LBA)","accept":["lba","lavage broncho alveolaire","lavage bronchoalveolaire"],"keywords":["lavage"],"explanation":"Le LBA est très performant pour le diagnostic des infections. Il est réalisé s'il est possible, une fois la cause cardiaque éliminée, et il est indiqué devant toute PID de l'immunodéprimé.","src":"p. 210, 213"},{"id":"p210-qroc-014","type":"QROC","rank":"B","objective":"p210-obj-10","tags":["diagnostic","pièges"],"difficulty":2,"question":"Pourquoi indique-t-on un LBA devant toute PID de l'immunodéprimé, même en l'absence de fièvre ?","answer":"Car une infection non fébrile est possible","accept":["infection non febrile","infection sans fievre","infection possible sans fievre","infection afebrile"],"keywords":["infect"],"explanation":"Chez l'immunodéprimé, une infection peut évoluer sans fièvre : l'absence de fièvre n'écarte donc pas une cause infectieuse.","src":"p. 213"},{"id":"p210-qroc-015","type":"QROC","rank":"B","objective":"p210-obj-10","tags":["urgence","traitement"],"difficulty":2,"question":"Quel germe opportuniste faut-il couvrir par le traitement probabiliste d'une PID aiguë fébrile en contexte d'immunosuppression, si l'imagerie est compatible ?","answer":"Pneumocystis jirovecii (pneumocystose)","accept":["pneumocystis","pneumocystose","jiroveci","p jiroveci","pneumocystis jirovecii"],"keywords":["pneumocyst"],"explanation":"Le traitement probabiliste couvre le pneumocoque et les agents intracellulaires (comme dans une PAC grave), et P. jirovecii si le contexte d'immunosuppression et l'imagerie sont compatibles.","src":"p. 213"},{"id":"p210-qroc-016","type":"QROC","rank":"B","objective":"p210-obj-10","tags":["urgence","traitement"],"difficulty":2,"question":"Quel traitement d'épreuve instaure-t-on devant une PID aiguë en cas de doute sur une insuffisance cardiaque ?","answer":"Les diurétiques","accept":["diuretique","diuretiques","test aux diuretiques","traitement diuretique"],"keywords":["diuretique"],"explanation":"En cas de doute sur une insuffisance cardiaque, on donne des diurétiques sans attendre la fin du bilan : l'œdème cardiogénique est fréquent et doit toujours être suspecté.","src":"p. 212, 213"},{"id":"p210-qroc-017","type":"QROC","rank":"B","objective":"p210-obj-10","tags":["urgence","traitement"],"difficulty":1,"question":"Que faut-il faire d'emblée d'un médicament potentiellement pneumotoxique devant une PID aiguë ?","answer":"L'arrêter immédiatement","accept":["arret immediat","arreter","l arreter","arret du medicament","stopper","arreter immediatement"],"keywords":["arret"],"explanation":"Tout médicament potentiellement pneumotoxique est arrêté immédiatement, sans attendre la fin du bilan. L'histoire médicamenteuse doit être détaillée, car des prises anciennes peuvent aussi être en cause.","src":"p. 213, 221"},{"id":"p210-qroc-018","type":"QROC","rank":"B","objective":"p210-obj-10","tags":["clinique"],"difficulty":1,"question":"Quel bruit pulmonaire sec, prédominant aux bases, peut s'entendre au cours d'une PID subaiguë ou chronique ?","answer":"Des crépitants secs de type Velcro","accept":["crepitants secs","crepitants velcro","rales crepitants secs","velcro","type velcro"],"keywords":["velcro"],"explanation":"Les crépitants secs de type Velcro aux bases font partie des signes d'appel, plus rares que la dyspnée d'effort et la toux sèche ; on les retrouve notamment dans la FPI.","src":"p. 214, 225"},{"id":"p210-qroc-019","type":"QROC","rank":"B","objective":"p210-obj-09","tags":["imagerie","diagnostic"],"difficulty":1,"question":"Quel examen d'imagerie est la pierre angulaire de l'orientation diagnostique d'une PID subaiguë ou chronique ?","answer":"Le scanner thoracique haute résolution (coupes fines)","accept":["scanner thoracique","scanner","tdm","tdm thoracique","tomodensitometrie","scanner haute resolution"],"keywords":["scanner"],"explanation":"Le scanner thoracique en haute résolution et en coupes fines est la pierre angulaire de l'orientation étiologique : l'analyse des lésions et de leur topographie permet de décrire des profils évocateurs.","src":"p. 210, 214, 221"},{"id":"p210-qroc-020","type":"QROC","rank":"B","objective":"p210-obj-11","tags":["imagerie"],"difficulty":1,"question":"Comment appelle-t-on une hyperdensité pulmonaire qui n'efface ni les contours des vaisseaux ni les parois bronchiques ?","answer":"Le verre dépoli","accept":["verre depoli","plages de verre depoli","plage de verre depoli"],"keywords":["verre"],"explanation":"Le verre dépoli n'efface pas les contours vasculaires ni les parois bronchiques, contrairement à la condensation alvéolaire qui les efface (avec parfois un bronchogramme aérique).","src":"p. 214, 216-217"},{"id":"p210-qroc-021","type":"QROC","rank":"B","objective":"p210-obj-11","tags":["imagerie"],"difficulty":1,"question":"Comment nomme-t-on des espaces kystiques aériques jointifs, à parois épaissies, disposés en couches sous-pleurales ?","answer":"Le rayon de miel","accept":["rayon de miel","rayons de miel","kystes en rayon de miel","aspect en rayon de miel"],"keywords":["miel"],"explanation":"Les kystes en rayon de miel, de siège sous-pleural, font partie de l'aspect de pneumopathie interstitielle commune de la fibrose pulmonaire idiopathique.","src":"p. 214, 219, 225"},{"id":"p210-qroc-022","type":"QROC","rank":"B","objective":"p210-obj-11","tags":["imagerie"],"difficulty":2,"question":"Comment nomme-t-on les dilatations bronchiques dues à la rétraction d'un parenchyme fibreux, alors que la paroi bronchique est normale ?","answer":"Les bronchectasies de traction","accept":["bronchectasies de traction","bronchectasie de traction","bronchiectasies de traction"],"keywords":["traction"],"explanation":"Ce ne sont pas de vraies bronchectasies : la paroi bronchique est normale mais tirée par la rétraction du parenchyme fibreux. C'est un signe associé de fibrose, avec la distorsion architecturale et la perte de volume.","src":"p. 214, 220"},{"id":"p210-qroc-023","type":"QROC","rank":"B","objective":"p210-obj-12","tags":["paraclinique"],"difficulty":1,"question":"Quel syndrome ventilatoire est typique des EFR d'une PID ?","answer":"Un trouble ventilatoire restrictif (TVR) pur","accept":["tvr","trouble ventilatoire restrictif","syndrome restrictif","tvr pur"],"keywords":["restrictif"],"explanation":"Le TVR pur associe une CPT abaissée, une baisse homogène de la capacité vitale et du VEMS, et un rapport VEMS/CVF supérieur à 70 %.","src":"p. 220"},{"id":"p210-qroc-024","type":"QROC","rank":"B","objective":"p210-obj-12","tags":["paraclinique","définition"],"difficulty":1,"question":"Quel seuil de capacité pulmonaire totale (CPT) caractérise le trouble ventilatoire restrictif d'une PID ?","answer":"CPT < 80 %","accept":["80","80 %","moins de 80 %","inferieure a 80 %","cpt inferieure a 80 %"],"keywords":["80"],"explanation":"Le TVR des PID se définit par une CPT inférieure à 80 % de la valeur théorique, avec un rapport VEMS/CVF supérieur à 70 % (baisse homogène des volumes et des débits).","src":"p. 220"},{"id":"p210-qroc-025","type":"QROC","rank":"B","objective":"p210-obj-12","tags":["paraclinique"],"difficulty":2,"question":"En dessous de quelle valeur théorique la DLCO est-elle considérée comme abaissée dans une PID ?","answer":"DLCO < 70 % de la valeur théorique","accept":["70","70 %","moins de 70 %","inferieure a 70 %"],"keywords":["70"],"explanation":"Une DLCO inférieure à 70 % de la valeur théorique témoigne d'un trouble de la diffusion alvéolo-capillaire ; elle s'associe au TVR et à l'hypoxémie d'effort.","src":"p. 220"},{"id":"p210-qroc-026","type":"QROC","rank":"B","objective":"p210-obj-12","tags":["paraclinique","pièges"],"difficulty":2,"question":"Quelle valeur d'orientation étiologique ont le trouble ventilatoire restrictif et l'hypoxémie d'une PID ?","answer":"Aucune","accept":["aucune","aucune valeur","pas de valeur","nulle","aucune valeur d orientation"],"keywords":["aucune"],"explanation":"Le TVR et l'hypoxémie n'ont aucune valeur d'orientation étiologique : les EFR servent au diagnostic positif et au suivi, tandis que l'orientation vers une cause repose surtout sur le scanner.","src":"p. 210, 221"},{"id":"p210-qroc-027","type":"QROC","rank":"B","objective":"p210-obj-04","tags":["clinique","étiologie"],"difficulty":1,"question":"Quelles deux expositions professionnelles responsables de pneumoconioses faut-il rechercher à l'interrogatoire d'une PID ?","answer":"L'amiante et la silice","accept":["amiante et silice","amiante silice","silice et amiante"],"keywords":["amiante","silice"],"explanation":"L'interrogatoire (+++) recherche les expositions professionnelles et domestiques : amiante et silice pour les pneumoconioses, antigènes organiques (oiseaux, foin moisi, moisissures) pour les PHS.","src":"p. 221"},{"id":"p210-qroc-028","type":"QROC","rank":"B","objective":"p210-obj-13","tags":["biologie"],"difficulty":1,"question":"Quel dosage sanguin recherche des IgG dirigées contre l'antigène responsable d'une pneumopathie d'hypersensibilité ?","answer":"Les précipitines sériques","accept":["precipitines","precipitines seriques","dosage des precipitines"],"keywords":["precipitine"],"explanation":"Les précipitines sériques sont des IgG dirigées contre l'antigène suspecté (déjections d'oiseaux, moisissures du foin…) ; elles confirment l'exposition mais pas, à elles seules, la maladie.","src":"p. 221, 227"},{"id":"p210-qroc-029","type":"QROC","rank":"B","objective":"p210-obj-13","tags":["biologie"],"difficulty":1,"question":"Quels deux dosages biologiques recherche-t-on dans le bilan d'une PID pour orienter vers une sarcoïdose ?","answer":"Calcémie et calciurie","accept":["calcemie et calciurie","calcemie calciurie","calciurie et calcemie"],"keywords":["calcemie","calciurie"],"explanation":"La calcémie et la calciurie sont dosées pour orienter vers une sarcoïdose ; le BNP cherche une insuffisance cardiaque, les ANCA une vascularite, les précipitines une PHS.","src":"p. 221"},{"id":"p210-qroc-030","type":"QROC","rank":"B","objective":"p210-obj-10","tags":["biologie","diagnostic"],"difficulty":2,"question":"Quelles cellules retrouvées au LBA sont en faveur d'une hémorragie alvéolaire ?","answer":"Les sidérophages","accept":["siderophages","siderophage","les siderophages"],"keywords":["siderophage"],"explanation":"Les sidérophages au LBA sont en faveur d'une hémorragie alvéolaire ; des cellules malignes ou des agents infectieux pathogènes y donnent également une certitude diagnostique.","src":"p. 222"},{"id":"p210-qroc-031","type":"QROC","rank":"B","objective":"p210-obj-10","tags":["paraclinique","pièges"],"difficulty":1,"question":"Quelles complications font éviter les biopsies transbronchiques dans les PID où elles ne sont pas contributives ?","answer":"Pneumothorax et hémoptysie","accept":["pneumothorax et hemoptysie","pneumothorax hemoptysie","hemoptysie et pneumothorax"],"keywords":["pneumothorax","hemoptysie"],"explanation":"Les biopsies transbronchiques sont utiles pour certaines PID (sarcoïdose, pneumopathie organisée, lymphangite carcinomateuse, miliaire tuberculeuse) ; dans les autres, elles sont non contributives et potentiellement dangereuses.","src":"p. 222-223"},{"id":"p210-qroc-032","type":"QROC","rank":"B","objective":"p210-obj-10","tags":["diagnostic"],"difficulty":1,"question":"Quelle étape doit précéder une biopsie pulmonaire chirurgicale ou une cryobiopsie transbronchique dans une PID ?","answer":"La discussion multidisciplinaire (DMD)","accept":["dmd","discussion multidisciplinaire","la discussion multidisciplinaire"],"keywords":["multidisciplinaire"],"explanation":"La biopsie chirurgicale ou la cryobiopsie n'est envisagée qu'après DMD, pour des PID non typiques, si un impact sur la prise en charge est attendu et en l'absence de contre-indication.","src":"p. 224"},{"id":"p210-qroc-033","type":"QROC","rank":"B","objective":"p210-obj-01","tags":["imagerie","diagnostic"],"difficulty":1,"question":"Quel aspect, au scanner puis à l'histologie, caractérise la fibrose pulmonaire idiopathique ?","answer":"La pneumopathie interstitielle commune (PIC)","accept":["pic","pneumopathie interstitielle commune","uip","usual interstitial pneumonia"],"keywords":["commune"],"explanation":"La FPI se traduit au scanner par un aspect de PIC : kystes en rayon de miel, réticulations intra-lobulaires et bronchectasies de traction, prédominant en sous-pleural et aux bases. Si une biopsie est faite, elle montre le même aspect.","src":"p. 225"},{"id":"p210-qroc-034","type":"QROC","rank":"B","objective":"p210-obj-01","tags":["traitement"],"difficulty":1,"question":"Quelle classe de médicaments constitue le traitement de fond de la FPI ?","answer":"Les antifibrosants","accept":["antifibrosants","antifibrosant","anti fibrosants","anti fibrosant"],"keywords":["fibrosant"],"explanation":"Les antifibrosants ralentissent le déclin de la fonction respiratoire, réduisent le risque d'exacerbation aiguë et améliorent probablement la survie.","src":"p. 225"},{"id":"p210-qroc-035","type":"QROC","rank":"B","objective":"p210-obj-08","tags":["étiologie","imagerie"],"difficulty":2,"question":"Quelle forme de PID est l'atteinte pulmonaire la plus fréquente au cours des connectivites ?","answer":"La PINS (pneumopathie interstitielle non spécifique)","accept":["pins","pneumopathie interstitielle non specifique","pneumopathies interstitielles non specifiques"],"keywords":["non specifique"],"explanation":"Dans les connectivites, la PINS est l'aspect le plus fréquent d'atteinte pulmonaire, et un scanner évocateur suffit alors pour la nommer. Elle peut aussi être secondaire à des médicaments.","src":"p. 226"},{"id":"p210-qroc-036","type":"QROC","rank":"B","objective":"p210-obj-05","tags":["biologie","diagnostic"],"difficulty":2,"question":"Quel aspect cytologique du LBA est typique d'une pneumopathie d'hypersensibilité en phase aiguë ?","answer":"Une alvéolite lymphocytaire","accept":["alveolite lymphocytaire","lymphocytose","lymphocytose alveolaire","predominance de lymphocytes"],"keywords":["lymphocyt"],"explanation":"Le LBA d'une PHS en phase aiguë montre typiquement une alvéolite lymphocytaire. Chez le fumeur, c'est plutôt le nombre de macrophages qui augmente (alvéolite macrophagique).","src":"p. 222, 227"},{"id":"p210-qroc-037","type":"QROC","rank":"B","objective":"p210-obj-05","tags":["biologie","pièges"],"difficulty":2,"question":"Que prouve la détection de précipitines sériques spécifiques (IgG) dans une PHS suspectée ?","answer":"L'exposition à l'antigène (pas la maladie)","accept":["exposition","l exposition","exposition a l antigene","preuve d exposition"],"keywords":["exposition"],"explanation":"Les précipitines confirment l'exposition mais ne permettent pas, seules, d'affirmer la maladie ; leur absence n'exclut pas le diagnostic.","src":"p. 227"},{"id":"p210-qroc-038","type":"QROC","rank":"B","objective":"p210-obj-02","tags":["imagerie","diagnostic"],"difficulty":2,"question":"Quelle anomalie pleurale, lorsqu'elle est présente au scanner, confirme l'exposition à l'amiante ?","answer":"Les plaques pleurales (plus ou moins calcifiées)","accept":["plaques pleurales","plaque pleurale","epaississements pleuraux","epaississement pleural"],"keywords":["pleura"],"explanation":"Les plaques pleurales, plus ou moins calcifiées, sont inconstantes ; quand elles existent, elles confirment l'exposition à l'amiante sans faire partie de l'asbestose proprement dite.","src":"p. 228"},{"id":"p210-qroc-039","type":"QROC","rank":"B","objective":"p210-obj-02","tags":["diagnostic","pièges"],"difficulty":2,"question":"Que prouve la présence de corps asbestosiques (ou ferrugineux) dans le LBA ou une biopsie pulmonaire ?","answer":"L'exposition à l'amiante, mais pas la maladie","accept":["exposition","l exposition","exposition a l amiante","la preuve de l exposition"],"keywords":["exposition"],"explanation":"Les corps asbestosiques affirment l'exposition mais pas la maladie, et ne sont pas indispensables : le diagnostic d'asbestose repose sur un contexte clinique, scanographique, fonctionnel et environnemental évocateur.","src":"p. 228"},{"id":"p210-qroc-040","type":"QROC","rank":"B","objective":"p210-obj-07","tags":["étiologie","imagerie"],"difficulty":2,"question":"Quel aspect scanographique évoque une lymphangite carcinomateuse ?","answer":"Épaississement nodulaire des septa interlobulaires (grandes mailles)","accept":["epaississement des septa interlobulaires","epaississement des cloisons interlobulaires","reticulations a larges mailles polyedriques","larges mailles polyedriques","grandes mailles polyedriques"],"keywords":["epaississ"],"explanation":"Le scanner montre un épaississement irrégulier et nodulaire des septa interlobulaires qui dessine un réseau à grandes mailles polyédriques, parfois avec des nodules. Les biopsies d'éperons de division bronchique confirment le plus souvent le diagnostic.","src":"p. 229"},{"id":"p210-qroc-041","type":"QROC","rank":"A","objective":"p210-obj-03","tags":["définition","imagerie"],"difficulty":2,"question":"Quelles sont les caractéristiques habituelles des opacités d'une PID à l'imagerie thoracique ?","answer":"Diffuses, non systématisées, bilatérales, habituellement symétriques","accept":["diffuses bilaterales symetriques","opacites diffuses non systematisees bilaterales et symetriques","diffuses non systematisees bilaterales"],"keywords":["diffuse","bilat","symetr"],"explanation":"Les PID réalisent des opacités parenchymateuses diffuses, non systématisées, bilatérales et habituellement symétriques ; le scanner thoracique est indispensable pour les analyser.","src":"p. 211"},{"id":"p210-qroc-042","type":"QROC","rank":"A","objective":"p210-obj-03","tags":["définition","physiopathologie"],"difficulty":2,"question":"Par quels types d'infiltrat l'interstitium pulmonaire peut-il être atteint dans une PID ?","answer":"Cellulaire, œdémateux ou fibreux","accept":["cellulaire oedemateux ou fibreux","cellulaire oedemateux fibreux","cellulaire oedemateux et fibreux"],"keywords":["cellul","oedem","fibr"],"explanation":"Les PID touchent l'interstitium par un infiltrat cellulaire, œdémateux ou fibreux ; dans certaines PID, les bronchioles et l'espace alvéolaire peuvent aussi être atteints.","src":"p. 211"},{"id":"p210-qroc-043","type":"QROC","rank":"A","objective":"p210-obj-03","tags":["définition","étiologie"],"difficulty":1,"question":"Quel groupe de PID de cause connue comprend la polyarthrite rhumatoïde, la sclérodermie et les myosites ?","answer":"Les PID des connectivites","accept":["pid des connectivites","pid au cours des connectivites","connectivites","connectivite"],"keywords":["connectiv"],"explanation":"La polyarthrite rhumatoïde, la sclérodermie et les myosites sont les connectivites citées parmi les causes connues de PID subaiguës ou chroniques ; la PINS est l'atteinte pulmonaire la plus fréquente des connectivites.","src":"p. 213, 226"},{"id":"p210-qcm-101","type":"QRM","rank":"A","objective":"p210-obj-03","tags":["définition","clinique"],"difficulty":1,"stem":"À propos des pneumopathies interstitielles diffuses (PID), quelles propositions sont exactes ?","options":[{"t":"Elles touchent essentiellement l'interstitium pulmonaire.","ok":true,"why":"Les PID atteignent surtout le tissu conjonctif de soutien des axes broncho-vasculaires et des septa."},{"t":"À l'imagerie : opacités diffuses, bilatérales, habituellement symétriques.","ok":true,"why":"C'est le point commun des PID à l'imagerie : opacités diffuses, non systématisées, bilatérales et le plus souvent symétriques."},{"t":"Une radiographie de thorax normale suffit à écarter le diagnostic de PID.","ok":false,"why":"Le scanner thoracique est indispensable : la radiographie peut être normale au début, par exemple dans la FPI."},{"t":"Dyspnée et toux sont non spécifiques ; les crépitants sont fréquents.","ok":true,"why":"Les signes cliniques sont peu spécifiques : dyspnée, toux, crépitants fréquents, hypoxémie à l'effort."},{"t":"Elles sont toutes de cause inconnue.","ok":false,"why":"Parmi les PID subaiguës ou chroniques, 35 % sont de cause connue (connectivites, PHS, médicaments, pneumoconioses…) et 65 % de cause inconnue."}],"explanation":"Les PID rassemblent de nombreuses entités qui ont en commun une atteinte de l'interstitium, des opacités diffuses bilatérales à l'imagerie (scanner indispensable) et des signes cliniques non spécifiques.","trap":"Une radiographie normale n'élimine pas une PID.","src":"p. 210-211, 225"},{"id":"p210-qcm-102","type":"QRM","rank":"B","objective":"p210-obj-06","tags":["étiologie","urgence"],"difficulty":2,"stem":"Un homme de 72 ans, hypertendu et coronarien, consulte pour une dyspnée aiguë évoluant depuis 4 jours, avec orthopnée et expectoration mousseuse. Il est apyrétique. Le scanner montre des opacités infiltrantes diffuses bilatérales. Quelles propositions sont exactes ?","options":[{"t":"L'œdème pulmonaire hémodynamique est l'hypothèse à évoquer en premier.","ok":true,"why":"Terrain (HTA, coronaropathie), orthopnée, expectoration mousseuse et absence de fièvre : tableau typique, d'une cause fréquente qui doit toujours être suspectée."},{"t":"Un bilan cardiologique (ECG, BNP, échographie cardiaque) est indispensable.","ok":true,"why":"Le bilan cardiologique est indispensable dans les PID aiguës non fébriles."},{"t":"Le LBA doit être réalisé avant tout bilan cardiaque.","ok":false,"why":"Le LBA est fait s'il est réalisable, une fois la cause cardiaque éliminée."},{"t":"Une biopsie pulmonaire chirurgicale est indiquée d'emblée.","ok":false,"why":"La biopsie chirurgicale n'est discutée qu'après DMD, pour des PID non typiques, avec un impact attendu sur la prise en charge."},{"t":"Un traitement anti-infectieux probabiliste à large spectre est systématique, même sans fièvre.","ok":false,"why":"Le traitement anti-infectieux probabiliste est proposé en présence de fièvre."}],"explanation":"Devant une PID aiguë non fébrile sur un terrain cardiovasculaire, l'œdème cardiogénique est à suspecter en premier et le bilan cardiologique est indispensable ; des diurétiques sont donnés en cas de doute.","trap":"L'absence de fièvre oriente vers l'œdème cardiogénique, pas vers une pneumonie.","src":"p. 210, 212-213"},{"id":"p210-qcm-103","type":"QRM","rank":"B","objective":"p210-obj-10","tags":["urgence","traitement"],"difficulty":3,"stem":"Un homme infecté par le VIH, non traité, présente depuis 10 jours une dyspnée croissante avec fièvre et des opacités interstitielles diffuses bilatérales. Quelles propositions sont exactes ?","options":[{"t":"Un LBA est indiqué, comme devant toute PID de l'immunodéprimé.","ok":true,"why":"Toute PID de l'immunodéprimé justifie un LBA, très performant pour les infections, une fois la cause cardiaque éliminée."},{"t":"Une couverture de P. jirovecii est justifiée si l'imagerie est compatible.","ok":true,"why":"La pneumocystose est couverte si le contexte d'immunosuppression et l'imagerie sont compatibles."},{"t":"Un traitement anti-infectieux peut être débuté avant la fin du bilan.","ok":true,"why":"La démarche diagnostique ne doit pas retarder la prise en charge : en présence de fièvre, on traite de façon probabiliste (pneumocoque, agents intracellulaires)."},{"t":"Il faut terminer tout le bilan diagnostique avant de débuter un traitement.","ok":false,"why":"C'est faux : l'enquête diagnostique ne doit jamais retarder le traitement."},{"t":"Un traitement antituberculeux probabiliste est à associer systématiquement.","ok":false,"why":"Il n'est envisagé que si l'imagerie évoque une miliaire et si la gravité empêche d'attendre une preuve bactériologique."}],"explanation":"Chez l'immunodéprimé fébrile avec une PID aiguë, on associe LBA et traitement probabiliste sans retard (pneumocoque, agents intracellulaires, P. jirovecii si le contexte et l'imagerie sont compatibles) ; la tuberculose n'est couverte qu'en cas d'imagerie de miliaire et de gravité.","src":"p. 212-213"},{"id":"p210-qcm-104","type":"QRM","rank":"B","objective":"p210-obj-10","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Quelles sont les circonstances de découverte classiques d'une PID subaiguë ou chronique ?","options":[{"t":"Une dyspnée d'effort d'apparition progressive, parfois avec toux sèche.","ok":true,"why":"Ce sont les signes d'appel les plus habituels, non spécifiques."},{"t":"Une découverte fortuite sur une imagerie thoracique.","ok":true,"why":"C'est une circonstance de découverte possible, plus rare."},{"t":"Le bilan d'une autre affection, en particulier une connectivite.","ok":true,"why":"La PID peut être découverte lors du bilan d'une connectivite connue."},{"t":"Un hippocratisme digital, signe très spécifique de la fibrose pulmonaire idiopathique.","ok":false,"why":"L'hippocratisme digital est peu spécifique ; il est seulement évocateur de FPI."},{"t":"Un début brutal avec détresse respiratoire en quelques heures.","ok":false,"why":"Les signes d'une PID subaiguë ou chronique apparaissent progressivement, et non en quelques heures."}],"explanation":"Une PID subaiguë ou chronique se révèle le plus souvent par une dyspnée d'effort progressive avec ou sans toux sèche ; plus rarement par des crépitants secs de type Velcro, un hippocratisme digital, une découverte fortuite ou le bilan d'une autre affection.","src":"p. 214"},{"id":"p210-qcm-105","type":"QRM","rank":"B","objective":"p210-obj-11","tags":["imagerie"],"difficulty":2,"stem":"À propos des lésions élémentaires scanographiques des PID, quelles propositions sont exactes ?","options":[{"t":"Un micronodule mesure moins de 3 mm.","ok":true,"why":"Les micronodules font moins de 3 mm ; les nodules mesurent de 3 à 30 mm."},{"t":"Le verre dépoli n'efface pas les contours des vaisseaux ni les parois bronchiques.","ok":true,"why":"C'est ce qui le distingue de la condensation alvéolaire."},{"t":"La condensation alvéolaire respecte les contours des vaisseaux et des parois bronchiques.","ok":false,"why":"C'est le verre dépoli qui les respecte ; la condensation alvéolaire les efface."},{"t":"Le rayon de miel correspond à des kystes isolés, de siège central.","ok":false,"why":"Ce sont des espaces kystiques jointifs, à parois épaissies, en couches successives sous-pleurales."},{"t":"Les bronchectasies de traction traduisent un épaississement inflammatoire de la paroi bronchique.","ok":false,"why":"La paroi bronchique est normale : la dilatation résulte de la traction exercée par la fibrose."}],"explanation":"Le verre dépoli (contours vasculaires et parois bronchiques visibles) s'oppose à la condensation alvéolaire (contours effacés). Les kystes en rayon de miel sont sous-pleuraux, et les bronchectasies de traction sont un signe associé de fibrose.","src":"p. 214, 216-217, 219-220"},{"id":"p210-qcm-106","type":"QRM","rank":"B","objective":"p210-obj-12","tags":["paraclinique","pièges"],"difficulty":2,"stem":"À propos des EFR au cours des PID, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Elles montrent un trouble ventilatoire restrictif pur.","ok":true,"why":"CPT < 80 %, baisse homogène de la capacité vitale et du VEMS, rapport VEMS/CVF > 70 %."},{"t":"La DLCO est classiquement normale dans les PID, seuls les volumes sont touchés.","ok":false,"why":"La DLCO est abaissée (< 70 % de la valeur théorique) : trouble de la diffusion alvéolo-capillaire."},{"t":"Le rapport VEMS/CVF est typiquement inférieur à 70 %.","ok":false,"why":"Dans un TVR pur, le rapport VEMS/CVF est supérieur à 70 % ; un trouble obstructif associé peut s'observer chez le fumeur ou dans certaines connectivites."},{"t":"Le profil restrictif permet de distinguer une FPI d'une PHS.","ok":false,"why":"Le TVR et l'hypoxémie n'ont aucune valeur d'orientation étiologique."},{"t":"L'hypoxémie est toujours présente au repos.","ok":false,"why":"Elle est souvent absente au repos et se démasque à l'effort, par une désaturation au test de marche de 6 minutes."}],"explanation":"Les EFR montrent un TVR pur avec baisse de la DLCO et une hypoxémie souvent limitée à l'effort, mais n'orientent pas vers une cause précise.","trap":"Les EFR confirment une PID mais ne disent pas laquelle.","src":"p. 220-221"},{"id":"p210-qcm-107","type":"QRM","rank":"B","objective":"p210-obj-13","tags":["biologie"],"difficulty":2,"stem":"Dans le bilan biologique d'une PID, quelles associations « examen – orientation recherchée » sont exactes ?","options":[{"t":"Précipitines sériques – pneumopathie d'hypersensibilité","ok":true,"why":"Ce sont des IgG dirigées contre l'antigène responsable de la PHS."},{"t":"Calcémie et calciurie – sarcoïdose","ok":true,"why":"Ces dosages sont demandés pour orienter vers une sarcoïdose."},{"t":"ANCA – vascularite","ok":true,"why":"Les ANCA sont recherchés pour dépister une vascularite."},{"t":"BNP – insuffisance rénale","ok":false,"why":"Le BNP cherche une insuffisance cardiaque ; l'insuffisance rénale est recherchée par la créatininémie."},{"t":"Facteur rhumatoïde et anti-CCP – pneumopathie d'hypersensibilité","ok":false,"why":"Ils sont demandés pour une connectivite ; la PHS relève des précipitines sériques."}],"explanation":"Le bilan oriente selon le contexte : précipitines (PHS), calcémie et calciurie (sarcoïdose), facteur rhumatoïde, anti-CCP, anticorps anti-nucléaires, anti-ADN (connectivites), ANCA (vascularites), BNP (insuffisance cardiaque), créatininémie (insuffisance rénale), NFS-CRP.","src":"p. 221"},{"id":"p210-qcm-108","type":"QRM","rank":"B","objective":"p210-obj-10","tags":["biologie","diagnostic"],"difficulty":2,"stem":"À propos du lavage broncho-alvéolaire (LBA) au cours des PID, quelles propositions sont exactes ?","options":[{"t":"Il est réalisé au cours d'une bronchoscopie souple.","ok":true,"why":"Le LBA se fait lors d'une fibroscopie bronchique."},{"t":"Chez le sujet sain, il contient surtout des macrophages (85 à 95 %).","ok":true,"why":"Les lymphocytes représentent 5 à 15 % des cellules."},{"t":"Chez le fumeur, le nombre et le pourcentage de macrophages augmentent.","ok":true,"why":"On parle d'alvéolite macrophagique."},{"t":"Des sidérophages sont en faveur d'une hémorragie alvéolaire.","ok":true,"why":"Avec les cellules malignes et les agents infectieux pathogènes, ils peuvent donner une certitude diagnostique."},{"t":"Il est contre-indiqué chez l'immunodéprimé en raison du risque infectieux.","ok":false,"why":"Au contraire, il est indiqué devant toute PID de l'immunodéprimé."}],"explanation":"Le LBA fournit une orientation selon sa formule cytologique : macrophages (sujet sain, fumeur), lymphocytes (PHS aiguë), sidérophages (hémorragie alvéolaire), cellules malignes ou germes pathogènes (certitude).","src":"p. 213, 222"},{"id":"p210-qcm-109","type":"QRM","rank":"B","objective":"p210-obj-10","tags":["diagnostic","paraclinique"],"difficulty":2,"stem":"À propos de l'histologie dans le diagnostic des PID, quelles propositions sont exactes ?","options":[{"t":"Elle intervient dans moins de 15 % des PID.","ok":true,"why":"La démarche diagnostique n'y fait appel que dans une minorité de cas."},{"t":"L'EBUS permet de ponctionner des adénopathies médiastinales et hilaires.","ok":true,"why":"C'est une biopsie à travers la paroi bronchique, indiquée par exemple dans la sarcoïdose, la lymphangite carcinomateuse, la tuberculose ganglionnaire ou un lymphome."},{"t":"Les biopsies transbronchiques sont sans risque dans les PID où elles ne sont pas contributives.","ok":false,"why":"Elles y sont potentiellement dangereuses (pneumothorax, hémoptysie)."},{"t":"La biopsie chirurgicale doit être réalisée d'emblée devant toute PID.","ok":false,"why":"Elle n'est discutée qu'après DMD, pour des PID non typiques, si un impact thérapeutique est attendu."},{"t":"Les biopsies d'éperons de division bronchique sont utiles pour la FPI.","ok":false,"why":"Elles servent aux processus lymphophiles diffus de la muqueuse bronchique : sarcoïdose et lymphangite carcinomateuse."}],"explanation":"L'histologie reste exceptionnelle et ciblée : biopsies d'éperons (sarcoïdose, lymphangite carcinomateuse), biopsies transbronchiques (sarcoïdose, pneumopathie organisée, lymphangite carcinomateuse, miliaire), EBUS pour les adénopathies, biopsie chirurgicale ou cryobiopsie après DMD.","src":"p. 222-224"},{"id":"p210-qcm-110","type":"QRM","rank":"B","objective":"p210-obj-10","tags":["diagnostic"],"difficulty":2,"stem":"Quelles étapes font partie de la démarche diagnostique devant une PID subaiguë ou chronique ?","options":[{"t":"Un interrogatoire détaillé (expositions, médicaments, connectivite).","ok":true,"why":"L'interrogatoire est un temps essentiel (+++) de l'orientation."},{"t":"Un scanner thoracique en haute résolution, en coupes fines.","ok":true,"why":"C'est la pierre angulaire de l'orientation diagnostique."},{"t":"Une fibroscopie bronchique avec LBA.","ok":true,"why":"Elle fait partie des étapes initiales du schéma diagnostique, avec des biopsies bronchiques si l'on suspecte une sarcoïdose ou une lymphangite carcinomateuse."},{"t":"Une discussion multidisciplinaire pour la très grande majorité des cas.","ok":true,"why":"La complexité du raisonnement la justifie dans la très grande majorité des PID."},{"t":"Une biopsie pulmonaire chirurgicale systématique chez tous les patients.","ok":false,"why":"Elle n'est faite qu'après DMD, si la PID est non typique, avec un impact attendu et sans contre-indication."}],"explanation":"La démarche est méthodique et graduelle : histoire clinique, examen, scanner haute résolution, biologie, fibroscopie avec LBA, puis biopsies transbronchiques ou ganglionnaires selon le scanner, et discussion multidisciplinaire avant toute biopsie chirurgicale.","src":"p. 224"},{"id":"p210-qcm-111","type":"QRM","rank":"B","objective":"p210-obj-10","tags":["clinique","étiologie"],"difficulty":2,"stem":"Que faut-il rechercher à l'interrogatoire devant une PID subaiguë ou chronique ?","options":[{"t":"Le tabagisme.","ok":true,"why":"Certaines PID s'observent presque exclusivement chez les fumeurs."},{"t":"Une consommation de drogues, quelle que soit la voie d'administration.","ok":true,"why":"Les drogues, ou les produits qui les coupent, peuvent provoquer des PID aiguës comme chroniques."},{"t":"Des médicaments ou une radiothérapie.","ok":true,"why":"L'histoire détaillée des prises médicamenteuses est indispensable."},{"t":"Des signes de connectivite : arthralgies, myalgies, syndrome sec, Raynaud.","ok":true,"why":"Ils orientent vers une PID associée à une connectivite."},{"t":"Seulement les médicaments introduits récemment, les prises anciennes pouvant être écartées.","ok":false,"why":"Les médicaments dont la prise est ancienne peuvent aussi être incriminés."}],"explanation":"L'interrogatoire (+++) explore le terrain (âge, sexe), le tabac, les drogues, les médicaments et la radiothérapie (même anciens), les expositions professionnelles et domestiques, et les signes de connectivite.","src":"p. 220-221"},{"id":"p210-qcm-112","type":"QRM","rank":"B","objective":"p210-obj-01","tags":["clinique","imagerie","traitement"],"difficulty":3,"stem":"Un homme de 68 ans, ancien fumeur, consulte pour une dyspnée d'effort d'aggravation progressive depuis 8 mois avec toux sèche. L'examen retrouve des crépitants secs de type Velcro aux bases et un hippocratisme digital. Le scanner montre des kystes en rayon de miel sous-pleuraux basaux et des bronchectasies de traction. Quelles propositions sont exactes ?","options":[{"t":"Ce tableau est celui d'une pneumopathie interstitielle commune, évocatrice de FPI.","ok":true,"why":"Kystes en rayon de miel et bronchectasies de traction sous-pleuraux et basaux : aspect de PIC."},{"t":"Les EFR montrent un trouble ventilatoire restrictif avec baisse de la DLCO.","ok":true,"why":"C'est le profil fonctionnel de la FPI ; l'hypoxémie peut n'apparaître qu'à l'effort."},{"t":"Le LBA est nécessaire pour poser le diagnostic positif.","ok":false,"why":"Le LBA ne fournit pas d'élément de diagnostic positif ; il peut seulement éliminer des diagnostics différentiels si le scanner est atypique."},{"t":"La biologie montre habituellement un syndrome inflammatoire et un bilan immunitaire positif.","ok":false,"why":"Dans la FPI, la biologie est normale et le bilan immunitaire négatif."},{"t":"Le traitement médicamenteux repose sur les antifibrosants.","ok":true,"why":"Ils ralentissent le déclin respiratoire, réduisent le risque d'exacerbation aiguë et améliorent probablement la survie."}],"explanation":"Le scanner est la pierre angulaire du diagnostic de FPI ; la biopsie n'est discutée (après DMD) que si le scanner est atypique et si elle modifie la prise en charge.","src":"p. 225"},{"id":"p210-qcm-113","type":"QRM","rank":"B","objective":"p210-obj-05","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Un homme de 50 ans, non fumeur, possède une volière. Il consulte pour une toux sèche et une dyspnée d'effort évoluant depuis 4 mois. Le LBA montre une lymphocytose franche et les précipitines sériques sont positives vis-à-vis des déjections d'oiseaux. Quelles propositions sont exactes ?","options":[{"t":"Une pneumopathie d'hypersensibilité est le diagnostic à évoquer.","ok":true,"why":"Antigène aviaire, lymphocytose au LBA et précipitines positives : tableau de PHS."},{"t":"Les précipitines positives confirment l'exposition, pas à elles seules la maladie.","ok":true,"why":"Le diagnostic repose sur un faisceau d'arguments cliniques, scanographiques, fonctionnels et environnementaux."},{"t":"L'absence de précipitines aurait exclu le diagnostic.","ok":false,"why":"L'absence de précipitines n'exclut pas le diagnostic."},{"t":"Une biopsie pulmonaire chirurgicale est indispensable pour affirmer le diagnostic de PHS.","ok":false,"why":"Le recours à la biopsie est exceptionnel dans la PHS."},{"t":"Le tabagisme est le principal facteur favorisant de cette maladie.","ok":false,"why":"Les PHS sont rares chez le fumeur."}],"explanation":"Dans une PHS, le terrain (exposition aux oiseaux, non-fumeur), le LBA lymphocytaire et la sérologie orientent ; l'éviction de l'antigène est la clé.","trap":"Des précipitines positives prouvent l'exposition, pas la maladie.","src":"p. 226-227"},{"id":"p210-qcm-114","type":"QRM","rank":"B","objective":"p210-obj-05","tags":["clinique","physiopathologie"],"difficulty":3,"stem":"À propos des deux types de pneumopathie d'hypersensibilité (PHS), quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"La forme non fibrosante débute souvent par un syndrome pseudo-grippal fébrile.","ok":true,"why":"Elle est le plus souvent aiguë ou subaiguë et son évolution peut être spontanément favorable après éviction."},{"t":"Des signes de fibrose au scanner améliorent le pronostic.","ok":false,"why":"L'existence de signes de fibrose aggrave nettement le pronostic."},{"t":"En phase aiguë, le LBA montre typiquement une alvéolite macrophagique.","ok":false,"why":"C'est une alvéolite lymphocytaire ; l'alvéolite macrophagique est celle du tabagisme."},{"t":"La fibrose de la forme fibrosante est toujours évitée par l'arrêt de l'exposition.","ok":false,"why":"Elle est le plus souvent évitable, mais pas toujours : elle peut évoluer pour son propre compte vers l'insuffisance respiratoire."},{"t":"La biopsie pulmonaire est systématique pour affirmer le diagnostic.","ok":false,"why":"Elle est exceptionnelle ; le diagnostic s'appuie sur un faisceau d'arguments cliniques, scanographiques, fonctionnels et environnementaux."}],"explanation":"On distingue la PHS non fibrosante (aiguë ou subaiguë, favorable après éviction) et la PHS fibrosante (pronostic aggravé, évolution possible pour son propre compte).","src":"p. 226-227"},{"id":"p210-qcm-115","type":"QRM","rank":"B","objective":"p210-obj-04","tags":["étiologie","diagnostic"],"difficulty":2,"stem":"À propos des pneumoconioses, quelles propositions sont exactes ?","options":[{"t":"Ce sont des fibroses secondaires à l'inhalation de particules minérales.","ok":true,"why":"Ce sont des PID de cause connue (silice, amiante)."},{"t":"Le curriculum laboris est crucial pour le diagnostic.","ok":true,"why":"Ce sont le plus souvent des maladies professionnelles justifiant une reconnaissance par la Sécurité sociale."},{"t":"La silicose est la plus fréquente des pneumoconioses en France.","ok":false,"why":"C'est l'asbestose ; la silicose est devenue rare en France."},{"t":"La présence de corps asbestosiques est indispensable au diagnostic d'asbestose.","ok":false,"why":"Ils affirment l'exposition mais pas la maladie et ne sont pas indispensables."},{"t":"L'asbestose est toujours symptomatique dès les premiers stades.","ok":false,"why":"Sa présentation clinique est aspécifique, voire totalement silencieuse."}],"explanation":"Les pneumoconioses sont des fibroses par inhalation de particules minérales ; l'asbestose est la plus fréquente en France et le curriculum laboris est un élément clé du diagnostic.","src":"p. 227-228"},{"id":"p210-qcm-116","type":"QRM","rank":"B","objective":"p210-obj-04","tags":["imagerie","étiologie"],"difficulty":2,"stem":"Un prothésiste dentaire ayant travaillé en milieu non protégé présente des micronodules diffus prédominant aux lobes supérieurs, confluant par endroits en masses, avec des adénopathies médiastinales calcifiées. Quelles propositions sont exactes ?","options":[{"t":"Le diagnostic évoqué est une silicose.","ok":true,"why":"Micronodules des lobes supérieurs confluant en masses pseudo-tumorales, exposition à la silice."},{"t":"Les calcifications ganglionnaires sont souvent « en coquille d'œuf ».","ok":true,"why":"C'est l'aspect classique des adénopathies médiastinales de la silicose."},{"t":"La phase de latence de cette maladie peut être très longue.","ok":true,"why":"Le délai entre l'exposition et la maladie peut être très long."},{"t":"La cause est l'inhalation de fibres d'amiante, responsables de la pneumoconiose.","ok":false,"why":"La silicose est due à la silice libre cristalline ; l'amiante est responsable de l'asbestose."},{"t":"Cette maladie reste la pneumoconiose la plus fréquente en France.","ok":false,"why":"Elle est devenue rare en France ; les cas actuels concernent notamment des prothésistes dentaires."}],"explanation":"La silicose, due à la silice libre cristalline, donne des micronodules diffus des lobes supérieurs pouvant confluer en masses pseudo-tumorales, avec des adénopathies calcifiées « en coquille d'œuf ».","src":"p. 228"},{"id":"p210-qcm-117","type":"QRM","rank":"B","objective":"p210-obj-07","tags":["diagnostic","étiologie"],"difficulty":2,"stem":"Une femme de 58 ans, traitée il y a deux ans pour un cancer du sein, présente une altération de l'état général, une toux sèche rebelle et une polypnée d'aggravation rapide. Le scanner montre un épaississement irrégulier et nodulaire des septa interlobulaires. Quelles propositions sont exactes ?","options":[{"t":"Une lymphangite carcinomateuse est le diagnostic à évoquer.","ok":true,"why":"Antécédent de tumeur, altération de l'état général, toux sèche rebelle, polypnée rapidement progressive et épaississement nodulaire des septa."},{"t":"Les biopsies d'éperons de division bronchique peuvent confirmer le diagnostic.","ok":true,"why":"Les biopsies d'éperons, voire les biopsies transbronchiques, confirment le plus souvent le diagnostic."},{"t":"Les cancers primitifs les plus fréquents sont bronchique, mammaire et digestif.","ok":true,"why":"Les cancers pancréatique et prostatique sont plus rarement en cause."},{"t":"Le scanner montre typiquement des kystes en rayon de miel sous-pleuraux et basaux.","ok":false,"why":"Les kystes en rayon de miel sont l'aspect de la FPI ; ici, les septa interlobulaires épaissis dessinent des grandes mailles polyédriques."},{"t":"Une biopsie pulmonaire chirurgicale est indispensable avant de conclure.","ok":false,"why":"Des biopsies endoscopiques suffisent le plus souvent."}],"explanation":"La lymphangite carcinomateuse associe toux sèche rebelle, polypnée rapidement progressive, altération de l'état général et antécédent de tumeur ; le scanner montre un réseau de septa épaissis à grandes mailles polyédriques.","src":"p. 229"},{"id":"p210-qcm-118","type":"QRM","rank":"B","objective":"p210-obj-08","tags":["imagerie","étiologie"],"difficulty":2,"stem":"À propos de la pneumopathie interstitielle non spécifique (PINS), quelles propositions sont exactes ?","options":[{"t":"Le terme couvre un aspect histologique et une entité anatomo-clinique.","ok":true,"why":"Par extension, on parle aussi de profil scanographique évocateur de PINS."},{"t":"Le scanner associe verre dépoli et réticulations, avec une distribution péribronchovasculaire.","ok":true,"why":"On note aussi un certain degré de respect de la zone sous-pleurale."},{"t":"La PINS idiopathique survient plus tard que la FPI et son pronostic est nettement moins bon.","ok":false,"why":"Elle survient plus jeune (< 50 ans) et son pronostic est meilleur que celui de la FPI."},{"t":"Le diagnostic de certitude de PINS idiopathique est clinique, sans biopsie.","ok":false,"why":"Il nécessite une biopsie pulmonaire."},{"t":"Le traitement de la PINS idiopathique repose uniquement sur les antifibrosants.","ok":false,"why":"Il repose sur les immunosuppresseurs et éventuellement les antifibrosants."}],"explanation":"La PINS est la forme pulmonaire la plus fréquente des connectivites ; la PINS idiopathique est plus précoce que la FPI et de meilleur pronostic, et se traite par immunosuppresseurs.","src":"p. 226"},{"id":"p210-qcm-119","type":"QRM","rank":"B","objective":"p210-obj-06","tags":["définition","traitement"],"difficulty":3,"stem":"À propos des fibroses pulmonaires progressives (FPP), quelles propositions sont exactes ?","options":[{"t":"La fibrose s'aggrave malgré un traitement optimal de la maladie causale.","ok":true,"why":"C'est la définition de la FPP."},{"t":"Les patients peuvent alors bénéficier des traitements antifibrosants.","ok":true,"why":"Comme dans la FPI, les antifibrosants sont proposés."},{"t":"Les critères reposent sur une évolution défavorable en 1 an ou moins.","ok":true,"why":"Évolution défavorable sur les composantes clinique, fonctionnelle et radiologique, évaluée sur 1 an au plus."},{"t":"La FPI en est l'archétype.","ok":true,"why":"La FPI est l'archétype de la fibrose pulmonaire progressive."},{"t":"Elle ne peut survenir qu'au cours de la FPI, jamais dans les autres PID fibrosantes.","ok":false,"why":"Toute PID fibrosante peut évoluer ainsi, avec autonomisation de la fibrose (par exemple une PHS aviaire)."}],"explanation":"Une FPP est une fibrose qui progresse malgré le traitement de la cause ; toute PID fibrosante peut en réaliser une et les antifibrosants sont alors proposés.","src":"p. 229-230"},{"id":"p210-qcm-120","type":"QRM","rank":"A","objective":"p210-obj-03","tags":["définition","épidémiologie"],"difficulty":1,"stem":"À propos de la classification des PID, quelles propositions sont exactes ?","options":[{"t":"Elles se classent selon l'évolution (aiguë, chronique) et la cause (connue, inconnue).","ok":true,"why":"Ce sont les deux critères de classement des PID."},{"t":"Une PID aiguë évolue depuis moins de 3 semaines.","ok":true,"why":"Au-delà, on parle de PID subaiguë ou chronique (PID-SC) avec une démarche différente."},{"t":"Parmi les PID subaiguës ou chroniques, les causes inconnues représentent environ 65 %.","ok":true,"why":"Les causes connues représentent environ 35 %."},{"t":"La fibrose pulmonaire idiopathique est la PID de cause connue la plus fréquente.","ok":false,"why":"Elle est idiopathique, donc de cause inconnue ; c'est la plus fréquente des PID idiopathiques."},{"t":"La sarcoïdose est classée parmi les PID dont la cause est connue et identifiée, comme les pneumoconioses.","ok":false,"why":"La sarcoïdose est une PID de cause inconnue : la FPI est la plus fréquente des PID de cause inconnue après la sarcoïdose."}],"explanation":"Les PID se classent selon l'évolution (aiguë ou subaiguë/chronique) et la cause (connue ou inconnue) ; les causes inconnues représentent 65 % des PID subaiguës ou chroniques.","src":"p. 210, 212-213, 225"},{"id":"p210-qru-101","type":"QRU","rank":"A","objective":"p210-obj-03","tags":["étiologie","définition"],"difficulty":2,"stem":"Parmi les PID suivantes, laquelle est de cause inconnue ?","options":[{"t":"Pneumoconiose (asbestose, silicose)","ok":false,"why":"Fibrose secondaire à l'inhalation de particules minérales (amiante, silice) : cause connue."},{"t":"Pneumopathie d'hypersensibilité","ok":false,"why":"Elle est liée à l'inhalation répétée d'antigènes organiques (oiseaux, foin moisi, moisissures) : cause connue."},{"t":"Pneumopathie médicamenteuse","ok":false,"why":"Le médicament pneumotoxique est la cause : PID de cause connue, d'où l'arrêt immédiat du médicament."},{"t":"PID associée à la polyarthrite rhumatoïde","ok":false,"why":"Les PID des connectivites (polyarthrite rhumatoïde, sclérodermie, myosites) font partie des causes connues."},{"t":"Fibrose pulmonaire idiopathique","ok":true,"why":"La FPI est une PID idiopathique, la plus fréquente des PID de cause inconnue après la sarcoïdose."}],"explanation":"Les PID idiopathiques (FPI, PINS, pneumopathie organisée cryptogénique) sont de cause inconnue, contrairement aux pneumoconioses, PHS, PID médicamenteuses et PID des connectivites dont la cause est identifiée.","src":"p. 213, 225"},{"id":"p210-qru-102","type":"QRU","rank":"B","objective":"p210-obj-06","tags":["étiologie"],"difficulty":2,"stem":"Parmi les propositions suivantes, laquelle ne fait PAS partie des quatre grandes étiologies des PID aiguës ?","options":[{"t":"Pneumonie communautaire grave ou à germe opportuniste","ok":false,"why":"Les causes infectieuses dominent les PID aiguës."},{"t":"Œdème aigu du poumon cardiogénique","ok":false,"why":"C'est une des quatre grandes étiologies, fréquente, à toujours suspecter."},{"t":"Syndrome de détresse respiratoire aiguë (SDRA)","ok":false,"why":"Le SDRA fait partie des quatre grandes étiologies."},{"t":"Exacerbation d'une PID subaiguë ou chronique préexistante","ok":false,"why":"C'est la quatrième grande étiologie, par exemple l'exacerbation de FPI."},{"t":"Pneumopathie médicamenteuse","ok":true,"why":"C'est une cause plus rare de PID aiguë, comme l'hémorragie intra-alvéolaire, la pneumopathie aiguë éosinophile ou certaines connectivites."}],"explanation":"Les quatre grandes étiologies des PID aiguës sont l'infection, l'œdème cardiogénique, le SDRA et l'exacerbation d'une PID subaiguë ou chronique préexistante ; les autres causes sont plus rares.","trap":"Rare ne veut pas dire négligeable : tout médicament pneumotoxique doit être arrêté immédiatement.","src":"p. 212-213"},{"id":"p210-qru-103","type":"QRU","rank":"B","objective":"p210-obj-11","tags":["imagerie","diagnostic"],"difficulty":2,"stem":"Un homme de 35 ans, fébrile, a été en contact avec un patient tuberculeux. Le scanner montre des micronodules de moins de 3 mm, à contours nets, répartis de façon diffuse dans les deux poumons. Quel diagnostic évoquer en premier ?","options":[{"t":"Miliaire tuberculeuse","ok":true,"why":"Contage tuberculeux, fièvre et micronodules à contours nets de distribution diffuse (hématogène)."},{"t":"Œdème pulmonaire hémodynamique","ok":false,"why":"Il est apyrétique et s'accompagne d'une cardiomégalie et d'opacités floues péri-hilaires."},{"t":"Sarcoïdose","ok":false,"why":"Les micronodules de la sarcoïdose suivent les lymphatiques (distribution périlymphatique, scissures « perlées »)."},{"t":"Silicose","ok":false,"why":"Les micronodules prédominent dans les lobes supérieurs, dans un contexte d'exposition à la silice."},{"t":"Lymphangite carcinomateuse","ok":false,"why":"Elle donne un épaississement irrégulier des septa interlobulaires, dans un contexte de cancer connu."}],"explanation":"Des micronodules de moins de 3 mm de distribution diffuse (hématogène) réalisent une miliaire ; en contexte fébrile avec contage, c'est la miliaire tuberculeuse, qui peut justifier un traitement probabiliste si la gravité interdit d'attendre.","src":"p. 212-215"},{"id":"p210-qru-104","type":"QRU","rank":"B","objective":"p210-obj-06","tags":["étiologie","clinique"],"difficulty":2,"stem":"Devant une PID aiguë, laquelle de ces associations oriente vers un œdème pulmonaire hémodynamique plutôt que vers une pneumonie infectieuse ?","options":[{"t":"Absence de fièvre, orthopnée, expectoration mousseuse","ok":true,"why":"C'est le tableau de l'œdème hémodynamique, sur un terrain d'HTA, de coronaropathie ou de valvulopathie."},{"t":"Fièvre et notion de contage (tuberculose, grippe, COVID-19)","ok":false,"why":"Fièvre et contage orientent vers une pneumonie infectieuse."},{"t":"Fièvre chez un patient immunodéprimé (VIH, greffe, cancer)","ok":false,"why":"Chez l'immunodéprimé fébrile, on pense aux infections, y compris opportunistes."},{"t":"Fièvre avec micronodules à contours nets sur l'imagerie","ok":false,"why":"Ils évoquent une miliaire tuberculeuse."},{"t":"Fièvre avec hémocultures et antigénuries positives","ok":false,"why":"Hémocultures et antigénuries font partie des éléments du diagnostic d'une pneumonie infectieuse."}],"explanation":"L'œdème hémodynamique est apyrétique, avec un terrain cardiovasculaire, une orthopnée, une expectoration mousseuse et à l'imagerie une cardiomégalie ; les pneumonies infectieuses sont fébriles.","src":"p. 212"},{"id":"p210-qru-105","type":"QRU","rank":"B","objective":"p210-obj-02","tags":["imagerie","diagnostic"],"difficulty":2,"stem":"Un ancien ouvrier exposé à l'amiante consulte pour une dyspnée d'effort. Le scanner montre des opacités linéaires aux bases et des plaques pleurales calcifiées. Quelle proposition est exacte ?","options":[{"t":"Les plaques pleurales confirment l'exposition à l'amiante.","ok":true,"why":"Quand elles sont présentes, elles confirment l'exposition ; elles ne font pas partie de l'asbestose proprement dite."},{"t":"Les plaques pleurales sont indispensables pour parler d'asbestose.","ok":false,"why":"Elles sont inconstantes."},{"t":"Des corps asbestosiques au LBA sont nécessaires pour affirmer l'asbestose.","ok":false,"why":"Ils affirment l'exposition mais pas la maladie, et ne sont pas indispensables."},{"t":"Une biopsie pulmonaire est obligatoire pour confirmer le diagnostic.","ok":false,"why":"Le diagnostic s'appuie sur un faisceau d'arguments cliniques, scanographiques, fonctionnels et environnementaux."},{"t":"Le profil scanographique est radicalement différent de celui d'une FPI.","ok":false,"why":"Le profil de l'asbestose est proche de celui de la FPI."}],"explanation":"L'asbestose, fibrose liée à l'amiante, a un profil scanographique proche de la FPI ; les plaques pleurales, inconstantes, confirment l'exposition sans être indispensables.","src":"p. 227-228"},{"id":"p210-qru-106","type":"QRU","rank":"B","objective":"p210-obj-07","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Un patient présente une dyspnée non fébrile d'aggravation progressive avec une expectoration abondante et claire. Le scanner montre des plages de verre dépoli associées à des condensations. Quel diagnostic évoquer ?","options":[{"t":"Adénocarcinome lépidique","ok":true,"why":"Dyspnée non fébrile progressive, expectoration abondante et claire, verre dépoli ± condensation : la cytologie de l'expectoration ou les biopsies confirment."},{"t":"Lymphangite carcinomateuse","ok":false,"why":"Elle donne une toux sèche rebelle et une polypnée rapidement progressive, avec des septa épaissis."},{"t":"Fibrose pulmonaire idiopathique","ok":false,"why":"Toux sèche, crépitants Velcro et aspect de PIC (rayon de miel, bronchectasies de traction)."},{"t":"Silicose","ok":false,"why":"Micronodules des lobes supérieurs, dans un contexte d'exposition à la silice."},{"t":"Œdème pulmonaire hémodynamique","ok":false,"why":"Il donne une dyspnée aiguë avec orthopnée et expectoration mousseuse, sans fièvre, sur un terrain cardiovasculaire."}],"explanation":"L'adénocarcinome lépidique est une prolifération tumorale à évoquer devant une dyspnée non fébrile avec expectoration abondante et claire et du verre dépoli, avec ou sans condensation.","src":"p. 229"},{"id":"p210-qru-107","type":"QRU","rank":"B","objective":"p210-obj-08","tags":["clinique","étiologie"],"difficulty":1,"stem":"Une femme de 55 ans consulte pour une dyspnée d'effort progressive avec des crépitants aux bases. Elle signale un phénomène de Raynaud, un syndrome sec et des arthralgies. Quelle orientation étiologique est la plus probable ?","options":[{"t":"PID associée à une connectivite","ok":true,"why":"Arthralgies, myalgies, syndrome sec et syndrome de Raynaud sont des signes fonctionnels évocateurs de connectivite."},{"t":"Pneumopathie d'hypersensibilité","ok":false,"why":"Elle suppose une exposition à des antigènes organiques inhalés (oiseaux, foin moisi, moisissures)."},{"t":"Silicose","ok":false,"why":"Elle suppose une exposition professionnelle à la silice."},{"t":"Lymphangite carcinomateuse","ok":false,"why":"Elle suppose un cancer connu, une altération de l'état général et une polypnée rapidement progressive."},{"t":"Œdème pulmonaire hémodynamique","ok":false,"why":"Il est aigu, avec orthopnée et expectoration mousseuse, sur un terrain cardiovasculaire."}],"explanation":"Les signes extra-respiratoires (arthralgies, myalgies, syndrome sec, Raynaud) orientent vers une PID de connectivite ; la PINS en est l'atteinte pulmonaire la plus fréquente.","src":"p. 221, 226"},{"id":"p210-qru-108","type":"QRU","rank":"B","objective":"p210-obj-05","tags":["imagerie"],"difficulty":2,"stem":"Quel aspect scanographique est typique d'une PHS non fibrosante ?","options":[{"t":"Plages de verre dépoli et/ou nodules flous peu denses, centro-lobulaires","ok":true,"why":"C'est l'aspect de la PHS non fibrosante, avec une radiographie montrant des opacités infiltrantes diffuses bilatérales."},{"t":"Kystes en rayon de miel sous-pleuraux prédominant aux bases","ok":false,"why":"C'est l'aspect de PIC de la FPI."},{"t":"Réticulations à larges mailles polyédriques par épaississement des septa","ok":false,"why":"C'est l'aspect de la lymphangite carcinomateuse."},{"t":"Micronodules périlymphatiques le long des scissures","ok":false,"why":"C'est l'aspect de la sarcoïdose."},{"t":"Masses pseudo-tumorales des lobes supérieurs avec adénopathies calcifiées","ok":false,"why":"C'est l'aspect de la silicose."}],"explanation":"Dans la PHS non fibrosante, le scanner montre du verre dépoli et/ou des nodules flous, peu denses, centro-lobulaires ; chacune des autres propositions décrit une autre PID.","src":"p. 214-215, 226, 228-229"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"p210-pareto","points":[{"id":"p210-par-01","rank":"A","cat":"définition","text":"PID = atteinte de l'**interstitium** : opacités **diffuses bilatérales** (**scanner** indispensable) ; dyspnée, toux, crépitants, hypoxémie à l'effort","src":"p. 210-211"},{"id":"p210-par-02","rank":"A","cat":"définition","text":"PID **aiguë** < **3 semaines** (sinon subaiguë ou chronique, PID-SC) ; PID-SC : cause connue 35 %, cause **inconnue 65 %**","src":"p. 212-213"},{"id":"p210-par-03","rank":"A","cat":"étiologie","text":"PID-SC dominées par **sarcoïdose**, **FPI**, **PID des connectivites** ; PID aiguës dominées par infection et œdème cardiogénique","src":"p. 210"},{"id":"p210-par-04","rank":"B","cat":"étiologie","text":"4 étiologies des PID aiguës : **infection**, **OAP** (à suspecter d'emblée, fréquent), **SDRA**, exacerbation de PID-SC","src":"p. 212-213"},{"id":"p210-par-05","rank":"B","cat":"examen","text":"PID aiguë fébrile ou immunodéprimé → **LBA** (cause cardiaque éliminée) ; PID aiguë non fébrile → **bilan cardiologique** (ECG, BNP, ETT)","src":"p. 210, 213"},{"id":"p210-par-06","rank":"B","cat":"traitement","text":"PID aiguë : ne pas retarder le traitement → **réanimation + O2** si détresse ; ATB probabiliste si fièvre (+ **P. jirovecii** si immunodéprimé) ; **diurétiques** si doute IC ; stop médicament pneumotoxique","src":"p. 213"},{"id":"p210-par-07","rank":"B","cat":"examen","text":"**Scanner thoracique** haute résolution (coupes fines) = pierre angulaire de l'orientation étiologique ; examen clinique et EFR rarement discriminants ; **DMD** pour la grande majorité des cas","src":"p. 210, 214, 221, 224"},{"id":"p210-par-08","rank":"B","cat":"examen","text":"Lésions TDM : **micronodules** (< 3 mm), réticulations, **verre dépoli** vs condensation, **rayon de miel** ; fibrose = bronchectasies de traction, distorsion, perte de volume","src":"p. 214"},{"id":"p210-par-09","rank":"B","cat":"chiffre","text":"EFR : **TVR pur** (**CPT < 80 %**, VEMS/CVF > 70 %), DLCO < 70 %, désaturation au TM6 ; **aucune valeur** d'orientation étiologique","src":"p. 220-221"},{"id":"p210-par-10","rank":"B","cat":"clinique","text":"Interrogatoire (+++) : **tabac**, drogues, **médicaments** / radiothérapie (même anciens), **expositions** pro et domestiques (amiante, silice, antigènes organiques), signes de connectivite","src":"p. 220-221"},{"id":"p210-par-11","rank":"B","cat":"examen","text":"Biologie : **précipitines** → PHS ; **calcémie, calciurie** → sarcoïdose ; FR, anti-CCP, AAN → connectivites ; **ANCA** → vascularites ; BNP → insuffisance cardiaque","src":"p. 221"},{"id":"p210-par-12","rank":"B","cat":"examen","text":"Histologie dans < **15 %** des PID : **BTB** (sarcoïdose, pneumopathie organisée, lymphangite carcinomateuse, miliaire), sinon risque de pneumothorax ; biopsie chirurgicale après **DMD**","src":"p. 222-224"},{"id":"p210-par-13","rank":"B","cat":"clinique","text":"**FPI** : âge moyen 68 ans, crépitants Velcro, hippocratisme ; TDM = **PIC** (rayon de miel, bronchectasies de traction, sous-pleural basal) ; **antifibrosants** ; survie médiane 3 ans sans traitement","src":"p. 225"},{"id":"p210-par-14","rank":"B","cat":"piège","text":"**PHS** : antigènes organiques inhalés, rare chez le fumeur ; LBA **lymphocytaire** ; **précipitines** = exposition, pas la maladie (leur absence n'exclut pas) ; éviction","src":"p. 226-227"},{"id":"p210-par-15","rank":"B","cat":"clinique","text":"**Asbestose** (la plus fréquente en France) : TDM proche de la FPI, **plaques pleurales** = exposition ; silicose : lobes supérieurs, **coquille d'œuf** ; curriculum laboris crucial","src":"p. 227-228"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
